from fractions import Fraction

def exit_stats(k, N, p):
    """(P(hit N), E[T]) for a walk from k with up chance p, stopped at 0 or N."""
    p = Fraction(p)
    if p == Fraction(1, 2):
        return Fraction(k, N), Fraction(k * (N - k))
    r = (1 - p) / p
    P = (1 - r ** k) / (1 - r ** N)
    return P, (N * P - k) / (2 * p - 1)
